SELECT chunk_id, file_id, scope, conversation_id, source_name, chunk_index,
       start_offset, end_offset, content, keywords, embedding, embedding_model, created_at
FROM zzl_ai_document_chunk
WHERE scope = #{scope}

    AND conversation_id = #{conversationId}


    AND file_id IN

        #{fileId}


ORDER BY file_id, chunk_index
LIMIT #{limit}

SELECT chunk_id, file_id, scope, conversation_id, source_name, chunk_index,
       start_offset, end_offset, content, keywords, embedding, embedding_model, created_at,
       MATCH(content, keywords) AGAINST (#{query} IN NATURAL LANGUAGE MODE) AS keyword_score
FROM zzl_ai_document_chunk
WHERE scope = #{scope}
  AND MATCH(content, keywords) AGAINST (#{query} IN NATURAL LANGUAGE MODE)

    AND conversation_id = #{conversationId}


    AND file_id IN

        #{fileId}


ORDER BY keyword_score DESC, file_id, chunk_index
LIMIT #{limit}
